#include "resident/domains/growth/growth_state_projection.hpp"
// 新课程才持有此来源；旧课程字段与字节由显式profile保持原样。
#include "innate_study_source.hpp"
#include "succession_personal_assets.hpp"
#include "resident/storage/common_checkpoint.hpp"
#include <set>
namespace hanmo::resident {namespace {
Status shape(const InnateStudySource& s){const std::set<StableId> fields={"actor_id","skill_id","origin_kind","origin_fact_id","observed_tick","bonus_bp","known_levels"};if(!s.field_order.empty()&&(s.field_order.size()!=fields.size()||std::set<StableId>(s.field_order.begin(),s.field_order.end())!=fields))return common_failure("InvalidInnateStudyFieldOrder");if(s.actor_id.empty()||s.actor_id.size()>256||s.skill_id.empty()||s.skill_id.size()>256||s.observed_tick<0||s.observed_tick>2147483647||s.bonus_bp<0||s.bonus_bp>1500||s.known_levels.size()>16)return common_failure("InvalidInnateStudySource");if(s.origin_kind!="authored_lineage"&&s.origin_kind!="biological_birth"&&s.origin_kind!="legacy_creation_unknown")return common_failure("InvalidInnateStudyOrigin");if((s.origin_kind=="authored_lineage")!=s.origin_fact_id.empty()||s.origin_fact_id.size()>256||(s.origin_kind=="legacy_creation_unknown"&&(!s.known_levels.empty()||s.bonus_bp!=0)))return common_failure("InvalidInnateStudyOrigin");for(const auto& row:s.known_levels.rows())if(row.first.empty()||row.first.size()>256||row.second<0||row.second>3)return common_failure("InvalidInnateStudyLevel");return common_success();}
}
Outcome<InnateStudySource> decode_innate_study_source(const BoundaryValue& value){try{using namespace boundary;auto unique=validate_succession_json_unique(value);if(!unique.ok)return {false,{},unique.error};fields(value,{"actor_id","skill_id","origin_kind","origin_fact_id","observed_tick","bonus_bp","known_levels"},{},"innate_study");InnateStudySource s;s.actor_id=get_string(value,"actor_id","");s.skill_id=get_string(value,"skill_id","");s.origin_kind=get_string(value,"origin_kind","");s.origin_fact_id=get_string(value,"origin_fact_id","");s.observed_tick=get_int(value,"observed_tick","");s.bonus_bp=get_int(value,"bonus_bp","");for(const auto& row:object(field(value,"known_levels",""),"known_levels"))s.known_levels.insert(row.first,integer(row.second,row.first));for(const auto& row:object(value,"innate_study"))s.field_order.push_back(row.first);auto valid=shape(s);if(!valid.ok)return {false,{},valid.error};return {true,std::move(s),{}};}catch(const boundary::DecodeFailure& e){return {false,{},e.error};}}
Status emit_innate_study_source_fields(ProjectionWriter& out,const InnateStudySource& s){auto valid=shape(s);if(!valid.ok)return out.reject(valid.error.original.code,"innate_study");out.field("actor_id",s.actor_id);out.field("skill_id",s.skill_id);out.field("origin_kind",s.origin_kind);out.field("origin_fact_id",s.origin_fact_id);out.field("observed_tick",s.observed_tick);out.field("bonus_bp",s.bonus_bp);out.object("known_levels",[&](auto& levels){for(const auto& row:s.known_levels.rows())levels.field(row.first,row.second);return levels.status();});return out.order_fields(s.field_order);}
BoundaryValue encode_innate_study_source(const InnateStudySource& s){BoundaryValue value;BoundaryProjectionWriter out(value);auto status=out.object("",[&](auto& w){return emit_innate_study_source_fields(w,s);});if(status.ok)status=out.finish();if(!status.ok){boundary::DecodeFailure failure(status.error.original.code,status.error.original.path);failure.error=status.error;throw failure;}return value;}
Status visit_innate_study_source(CodecVisitor& c,InnateStudySource& s){c.field("actor_id",s.actor_id);c.field("skill_id",s.skill_id);c.field("origin_kind",s.origin_kind);c.field("origin_fact_id",s.origin_fact_id);c.field("observed_tick",s.observed_tick);c.field("bonus_bp",s.bonus_bp);common_checkpoint::table(c,"known_levels",s.known_levels,[](auto& v,auto& x){return v.field("value",x);});common_checkpoint::strings(c,"field_order",s.field_order);auto status=c.status();if(!status.ok)return status;auto valid=shape(s);return valid.ok?status:c.reject(valid.error.original.code);}
}
